// 反例 2：MyBatis ${} 和 order by 拼接
// <select> select * from goods order by ${sort} ${dir} </select>
// sort 传入 "price; drop table goods --" 即可执行 DDL

// 正例 1：JDBC PreparedStatement，值位置用 ?
String sql = "select * from user where name = ? and pwd = ?";
try (PreparedStatement ps = conn.prepareStatement(sql)) {
    ps.setString(1, name);
    ps.setString(2, pwd);
    try (ResultSet rs = ps.executeQuery()) { /* ... */ }
}

// 正例 2：IN 子句按数组长度生成占位符
String placeholders = ids.stream().map(i -> "?").collect(Collectors.joining(","));
String sql2 = "select * from goods where id in (" + placeholders + ")";
try (PreparedStatement ps = conn.prepareStatement(sql2)) {
    for (int i = 0; i < ids.size(); i++) ps.setLong(i + 1, ids.get(i));
}

// 正例 3：order by 走服务端白名单
Map<String, String> SORT_WHITELIST = Map.of(
    "createTime", "created_at",
    "price",      "price"
);
String col = SORT_WHITELIST.getOrDefault(req.getSort(), "created_at");
String dir = "asc".equalsIgnoreCase(req.getDir()) ? "asc" : "desc";
String sql3 = "select * from goods order by " + col + " " + dir + " limit ?";
// 拼回去的 col/dir 都来自服务端常量，用户输入只决定 key,不直接进入 SQL
